window.CIVIL_SET_DATA["past-04"] = {"title":"Past Paper Set 4","negativeMarking":0,"chapters":[{"name":"Basic Civil Engineering","questions":[{"id":"PAST-04-018","src":"PAST-04-018","text":"In a mass haul diagram, if the end is negative, what does it mean?","options":[{"key":"a","text":"Balanced"},{"key":"b","text":"Borrow"},{"key":"c","text":"Surplus"},{"key":"d","text":"Cannot be said exactly"}],"answer":"b","explanation":"A final ordinate below the base line means the fill exceeds the cut over the length, so the shortage must be borrowed.","marks":1,"source":{"kind":"past","set":4,"question":18,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q18 · 1 mark"},"topic":"ACiE0106"},{"id":"PAST-04-019","src":"PAST-04-019","text":"Which is the weakest bond?","options":[{"key":"a","text":"Flemish bond"},{"key":"b","text":"English bond"},{"key":"c","text":"Raking bond"},{"key":"d","text":"Header bond"}],"answer":"c","explanation":"Raking bond bricks are laid at an angle (diagonal or herring-bone) as a filler bond inside thick walls, which gives it the least structural integrity of these bonds. English bond is the strongest.","marks":1,"source":{"kind":"past","set":4,"question":19,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q19 · 1 mark"},"topic":"ACiE0103"},{"id":"PAST-04-020","src":"PAST-04-020","text":"Which lime is used in lime mortar?","options":[{"key":"a","text":"Quick lime"},{"key":"b","text":"Fat lime"},{"key":"c","text":"Hydraulic lime"},{"key":"d","text":"Ump lime"}],"answer":"c","explanation":"Hydraulic lime sets under water and gives a stronger mortar for masonry. Fat lime is used mainly for plastering and whitewashing.","marks":1,"source":{"kind":"past","set":4,"question":20,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q20 · 1 mark"},"topic":"ACiE0101"},{"id":"PAST-04-029","src":"PAST-04-029","text":"The mixture of cement, sand and coarse aggregate is increased by what % to get the dry volume of concrete?","options":[{"key":"a","text":"10-20"},{"key":"b","text":"30-40"},{"key":"c","text":"50-55"},{"key":"d","text":"40-50"}],"answer":"c","explanation":"Voids between particles fill during mixing, so the dry-material volume is about 1.52–1.57 times the wet volume. That is an increase of about 50–55%.","marks":1,"source":{"kind":"past","set":4,"question":29,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q29 · 1 mark"},"topic":"ACiE0106"},{"id":"PAST-04-031","src":"PAST-04-031","text":"On which scale are maps drawn?","options":[{"key":"a","text":"Enlarging"},{"key":"b","text":"Reducing"},{"key":"c","text":"Balanced"},{"key":"d","text":"All of the above"}],"answer":"b","explanation":"Maps show large ground areas on small sheets, so they use a reducing scale (for example 1:25,000).","marks":1,"source":{"kind":"past","set":4,"question":31,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q31 · 1 mark"},"topic":"ACiE0105"},{"id":"PAST-04-061","src":"PAST-04-061","text":"Plastic bitumen is used in","options":[{"key":"a","text":"Road pavement"},{"key":"b","text":"Expansion joint"},{"key":"c","text":"Filling cracks"},{"key":"d","text":"Paints"}],"answer":"c","explanation":"Plastic bitumen is bitumen mixed with a thinner and an inert filler. It is used to fill cracks in masonry and stop leaks.","marks":2,"source":{"kind":"past","set":4,"question":61,"marks":2,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q61 · 2 marks"},"topic":"ACiE0101"},{"id":"PAST-04-069","src":"PAST-04-069","text":"Find the CG of a trapezoidal section of depth h with parallel sides a and b, measured from the base b.","options":[{"key":"a","text":"h/2·(b+2a)/(b+a)"},{"key":"b","text":"h/2·(b+2a)/(b−a)"},{"key":"c","text":"h/3·(b+2a)/(b+a)"},{"key":"d","text":"h/3·(b+2a)/(b−a)"}],"answer":"c","explanation":"Measured from the parallel side b, the centroid of a trapezium lies at ȳ = (h/3)(b+2a)/(a+b).","marks":2,"source":{"kind":"past","set":4,"question":69,"marks":2,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q69 · 2 marks"},"topic":"ACiE0104"},{"id":"PAST-04-071","src":"PAST-04-071","text":"If B is the formation width, d the depth and the side slope is s:1, what is the area of the cross section?","options":[{"key":"a","text":"Bd + s<sup>2</sup>d"},{"key":"b","text":"Bd + sd<sup>2</sup>"},{"key":"c","text":"Bd + s<sup>2</sup>d<sup>2</sup>"},{"key":"d","text":"Bd + sd"}],"answer":"b","explanation":"The section is a rectangle \\(Bd\\) plus two triangles of total area \\[2 \\times \\dfrac{1}{2} \\times sd \\times d = sd^2\\] so \\(A = Bd + sd^2\\).","marks":2,"source":{"kind":"past","set":4,"question":71,"marks":2,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q71 · 2 marks"},"topic":"ACiE0106"},{"id":"PAST-04-076","src":"PAST-04-076","text":"In a closed traverse, the sum of the north latitudes is more than the sum of the south latitudes and the sum of the west departures is more than the sum of the east departures. The bearing of the closing line is in the","options":[{"key":"a","text":"NE quadrant"},{"key":"b","text":"SE quadrant"},{"key":"c","text":"NW quadrant"},{"key":"d","text":"SW quadrant"}],"answer":"b","explanation":"The traverse closes north and west of the starting point. The closing line runs from that end point back to the start, i.e. towards the south-east.","marks":2,"source":{"kind":"past","set":4,"question":76,"marks":2,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q76 · 2 marks"},"topic":"ACiE0105"}]},{"name":"Soil Mechanics and Foundation Engineering","questions":[{"id":"PAST-04-003","src":"PAST-04-003","text":"The critical hydraulic gradient is formed if","options":[{"key":"a","text":"Seepage is upward"},{"key":"b","text":"Flow is upward"},{"key":"c","text":"Effective stress is zero"},{"key":"d","text":"All of the above"}],"answer":"d","explanation":"At the critical gradient \\[i_c = \\dfrac{G - 1}{1 + e}\\] the upward seepage force equals the submerged weight, so the effective stress drops to zero (quick condition).","marks":1,"source":{"kind":"past","set":4,"question":3,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q3 · 1 mark"},"topic":"ACiE0202"},{"id":"PAST-04-013","src":"PAST-04-013","text":"Consolidation settlement is calculated for","options":[{"key":"a","text":"a sand layer when the water table is far below"},{"key":"b","text":"a sand layer with the water table below the base of footing"},{"key":"c","text":"a clay layer with the water table at the ground surface"},{"key":"d","text":"none of these"}],"answer":"c","explanation":"Consolidation settlement is significant only in saturated, low-permeability soils such as clay, where excess pore pressure dissipates slowly. Sands settle almost immediately.","marks":1,"source":{"kind":"past","set":4,"question":13,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q13 · 1 mark"},"topic":"ACiE0206"},{"id":"PAST-04-021","src":"PAST-04-021","text":"At what minimum depth below the soil surface is a footing provided?","options":[{"key":"a","text":"400 mm"},{"key":"b","text":"500 mm"},{"key":"c","text":"600 mm"},{"key":"d","text":"700 mm"}],"answer":"b","explanation":"Footings should be taken at least 0.5 m below natural ground level (IS 1080 / IS 1904). This puts the base below topsoil, frost, shrinkage cracks and weathering.","marks":1,"source":{"kind":"past","set":4,"question":21,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q21 · 1 mark"},"topic":"ACiE0205"},{"id":"PAST-04-032","src":"PAST-04-032","text":"Which of the following is a pile foundation?","options":[{"key":"a","text":"Shallow"},{"key":"b","text":"Deep"},{"key":"c","text":"Shallow and deep"},{"key":"d","text":"Open foundation"}],"answer":"b","explanation":"Piles transfer load to deeper, stronger strata by end bearing and skin friction, so they are deep foundations.","marks":1,"source":{"kind":"past","set":4,"question":32,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q32 · 1 mark"},"topic":"ACiE0205"},{"id":"PAST-04-052","src":"PAST-04-052","text":"Consolidation settlement occurs due to","options":[{"key":"a","text":"Expulsion of air voids"},{"key":"b","text":"Expulsion of water from voids"},{"key":"c","text":"Both (a) and (b)"},{"key":"d","text":"Readjustment of soil molecules"}],"answer":"b","explanation":"Consolidation is the gradual volume decrease of a saturated soil as pore water is squeezed out under sustained load. Expulsion of air is compaction.","marks":1,"source":{"kind":"past","set":4,"question":52,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q52 · 1 mark"},"topic":"ACiE0206"}]},{"name":"Basic Water Resources Engineering","questions":[{"id":"PAST-04-025","src":"PAST-04-025","text":"The Bernoulli equation states that","options":[{"key":"a","text":"discharge is constant throughout the section"},{"key":"b","text":"energy is constant for one streamline and is different from another streamline"},{"key":"c","text":"energy is constant throughout the flow"},{"key":"d","text":"none of the above"}],"answer":"b","explanation":"For steady, ideal, incompressible flow the total head is constant along a streamline. In rotational flow each streamline can carry a different constant; only in irrotational flow is it the same everywhere.","marks":1,"source":{"kind":"past","set":4,"question":25,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q25 · 1 mark"},"topic":"ACiE0303"},{"id":"PAST-04-033","src":"PAST-04-033","text":"A Newtonian fluid is one which","options":[{"key":"a","text":"does not follow Newton's law of viscosity"},{"key":"b","text":"is a mathematical concept"},{"key":"c","text":"follows that shear stress is directly proportional to velocity gradient"},{"key":"d","text":"has properties of real fluid"}],"answer":"c","explanation":"A Newtonian fluid obeys \\[\\tau = \\mu\\dfrac{du}{dy}\\] with a constant viscosity independent of the rate of shear. Water and air are examples.","marks":1,"source":{"kind":"past","set":4,"question":33,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q33 · 1 mark"},"topic":"ACiE0301"},{"id":"PAST-04-034","src":"PAST-04-034","text":"The length of a hydraulic jump is equal to","options":[{"key":"a","text":"3 times the jump height"},{"key":"b","text":"5-7 times the jump height"},{"key":"c","text":"greater than 10 times the jump height"},{"key":"d","text":"12 times the jump height"}],"answer":"b","explanation":"The length of a hydraulic jump is about 5–7 times its height (y<sub>2</sub> − y<sub>1</sub>), roughly 6 times on average.","marks":1,"source":{"kind":"past","set":4,"question":34,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q34 · 1 mark"},"topic":"ACiE0305"},{"id":"PAST-04-035","src":"PAST-04-035","text":"Which method gives an accurate estimate of average rainfall in a hilly catchment?","options":[{"key":"a","text":"Isohyetal method"},{"key":"b","text":"Normal ratio method"},{"key":"c","text":"Arithmetic mean method"},{"key":"d","text":"Thiessen polygon method"}],"answer":"a","explanation":"Isohyets can be drawn to follow the orographic effect of the terrain, so the isohyetal method is the most accurate for hilly catchments.","marks":1,"source":{"kind":"past","set":4,"question":35,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q35 · 1 mark"},"topic":"ACiE0306"},{"id":"PAST-04-036","src":"PAST-04-036","text":"Which among the following methods of rain gauging is very accurate?","options":[{"key":"a","text":"Arithmetic mean method"},{"key":"b","text":"Thiessen method"},{"key":"c","text":"Iso-hyetal method"},{"key":"d","text":"Recording type"}],"answer":"d","explanation":"A recording (self-registering) gauge continuously records the cumulative rainfall, giving intensity and duration as well as depth. The other options are averaging methods, not gauges.","marks":1,"source":{"kind":"past","set":4,"question":36,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q36 · 1 mark"},"topic":"ACiE0306"},{"id":"PAST-04-048","src":"PAST-04-048","text":"In the case of the most economical trapezoidal section, the top width is equal to","options":[{"key":"a","text":"Double of the side slope"},{"key":"b","text":"Sum of the side slope"},{"key":"c","text":"Bottom width"},{"key":"d","text":"Double of flow depth"}],"answer":"a","explanation":"For the most efficient trapezoidal section, half the top width equals the length of one sloping side, so the top width is twice the sloping-side length (the sum of both sloping sides).","marks":1,"source":{"kind":"past","set":4,"question":48,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q48 · 1 mark"},"topic":"ACiE0305"},{"id":"PAST-04-056","src":"PAST-04-056","text":"The head loss at the entrance of the pipe is …… that at its exit.","options":[{"key":"a","text":"Half"},{"key":"b","text":"Equal"},{"key":"c","text":"Twice"},{"key":"d","text":"Four times"}],"answer":"a","explanation":"The entrance and exit losses are \\[h_{en} = 0.5\\dfrac{V^2}{2g}, \\qquad h_{ex} = \\dfrac{V^2}{2g}\\] so the entrance loss is half the exit loss.","marks":1,"source":{"kind":"past","set":4,"question":56,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q56 · 1 mark"},"topic":"ACiE0304"},{"id":"PAST-04-063","src":"PAST-04-063","text":"A flow control valve at the end of a 1 km long pipe is closed gradually in 10 seconds. If the rise of pressure head due to water hammer is 20 m of water, what was the velocity of water before the valve closure?","options":[{"key":"a","text":"4 m/s"},{"key":"b","text":"8 m/s"},{"key":"c","text":"6 m/s"},{"key":"d","text":"2 m/s"}],"answer":"d","explanation":"For gradual closure, \\[h = \\dfrac{LV}{gT}\\] so \\[\\begin{aligned} V &amp;= \\dfrac{hgT}{L} = \\dfrac{20 \\times 9.81 \\times 10}{1000} \\\\ &amp;\\approx 1.96 \\end{aligned}\\] or about 2 m per s.","marks":2,"source":{"kind":"past","set":4,"question":63,"marks":2,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q63 · 2 marks"},"topic":"ACiE0304"},{"id":"PAST-04-073","src":"PAST-04-073","text":"The piezometric head for a static fluid","options":[{"key":"a","text":"remains constant only in a horizontal plane"},{"key":"b","text":"remains constant at all points in the liquid"},{"key":"c","text":"decreases linearly with depth below a free surface"},{"key":"d","text":"increases linearly with depth below a free surface"}],"answer":"b","explanation":"In a static fluid p/γ + z is the same everywhere: pressure head increases with depth exactly as the elevation head decreases.","marks":2,"source":{"kind":"past","set":4,"question":73,"marks":2,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q73 · 2 marks"},"topic":"ACiE0302"},{"id":"PAST-04-078","src":"PAST-04-078","text":"Two soap bubbles have d and 2d diameter respectively. Which bubble has more internal pressure?","options":[{"key":"a","text":"With diameter d"},{"key":"b","text":"With diameter 2d"},{"key":"c","text":"Same for both bubbles"},{"key":"d","text":"Cannot be said until calculated"}],"answer":"a","explanation":"A soap bubble has two surfaces, so \\[\\Delta p = \\dfrac{8\\sigma}{d}\\] The smaller bubble has the higher pressure (twice that of the 2d bubble).","marks":2,"source":{"kind":"past","set":4,"question":78,"marks":2,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q78 · 2 marks"},"topic":"ACiE0301"}]},{"name":"Structural Mechanics","questions":[{"id":"PAST-04-005","src":"PAST-04-005","text":"The maximum bending moment due to a train of wheel loads on a simply supported girder","options":[{"key":"a","text":"always occurs at the centre of span"},{"key":"b","text":"always occurs under a wheel load"},{"key":"c","text":"never occurs under a wheel load"},{"key":"d","text":"None of these"}],"answer":"b","explanation":"For concentrated moving loads the bending-moment diagram is linear between loads, so the absolute maximum always occurs under one of the wheel loads (near midspan, placed by the resultant rule).","marks":1,"source":{"kind":"past","set":4,"question":5,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q5 · 1 mark"},"topic":"ACiE0404"},{"id":"PAST-04-006","src":"PAST-04-006","text":"Strain energy in a simply supported beam loaded with point load W at centre is","options":[{"key":"a","text":"Wl<sup>3</sup>/48EI"},{"key":"b","text":"Wl<sup>2</sup>/48EI"},{"key":"c","text":"W<sup>2</sup>l<sup>3</sup>/96EI"},{"key":"d","text":"Wl<sup>2</sup>/96EI"}],"answer":"c","explanation":"The strain energy is \\[\\begin{aligned} U &amp;= \\dfrac{1}{2}W\\delta = \\dfrac{1}{2}W \\times \\dfrac{Wl^3}{48EI} \\\\ &amp;= \\dfrac{W^2l^3}{96EI} \\end{aligned}\\]","marks":1,"source":{"kind":"past","set":4,"question":6,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q6 · 1 mark"},"topic":"ACiE0402"},{"id":"PAST-04-007","src":"PAST-04-007","text":"The correct relation between shear force and moment is","options":[{"key":"a","text":"S = dM/dx"},{"key":"b","text":"M = dS/dx"},{"key":"c","text":"dM/dS = x"},{"key":"d","text":"dS/dM = x"}],"answer":"a","explanation":"The shear force at a section is the rate of change of bending moment along the span: \\[S = \\dfrac{dM}{dx}, \\qquad \\dfrac{dS}{dx} = -w\\]","marks":1,"source":{"kind":"past","set":4,"question":7,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q7 · 1 mark"},"topic":"ACiE0401"},{"id":"PAST-04-023","src":"PAST-04-023","text":"In a propped cantilever beam, the plastic hinge is located at what distance from the propped end when subjected to UDL?","options":[{"key":"a","text":"0 L"},{"key":"b","text":"0.25 L"},{"key":"c","text":"0.414 L"},{"key":"d","text":"0.5 L"}],"answer":"c","explanation":"Under UDL the hinges form at the fixed end and at the sagging-moment point \\[x = (\\sqrt{2} - 1)L \\approx 0.414L\\] from the propped end. This gives the collapse load \\[w_u = \\dfrac{11.66M_p}{L^2}\\]","marks":1,"source":{"kind":"past","set":4,"question":23,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q23 · 1 mark"},"topic":"ACiE0406"},{"id":"PAST-04-037","src":"PAST-04-037","text":"In the case of long columns, direct stress is …… compared to bending stress.","options":[{"key":"a","text":"More"},{"key":"b","text":"Less"},{"key":"c","text":"Same"},{"key":"d","text":"Negligible"}],"answer":"d","explanation":"A long column fails by buckling; the bending stress due to lateral deflection governs and the direct stress is very small in comparison.","marks":1,"source":{"kind":"past","set":4,"question":37,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q37 · 1 mark"},"topic":"ACiE0403"},{"id":"PAST-04-060","src":"PAST-04-060","text":"The maximum shear stress is …… times the average shear stress for rectangular beams.","options":[{"key":"a","text":"1.5"},{"key":"b","text":"1.33"},{"key":"c","text":"1.7"},{"key":"d","text":"2.36"}],"answer":"a","explanation":"For a rectangular section, at the neutral axis, \\[\\tau_{max} = \\dfrac{3V}{2bd} = 1.5\\,\\tau_{avg}\\] It is \\(\\dfrac{4}{3}\\) for a circular section.","marks":1,"source":{"kind":"past","set":4,"question":60,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q60 · 1 mark"},"topic":"ACiE0403"},{"id":"PAST-04-077","src":"PAST-04-077","text":"The Euler's crippling load for a 2 m long slender steel rod of uniform cross-section hinged at both ends is 1 kN. The Euler's crippling load for a 1 m long steel rod of the same cross-section and hinged at both ends will be","options":[{"key":"a","text":"2 kN"},{"key":"b","text":"4 kN"},{"key":"c","text":"6 kN"},{"key":"d","text":"8 kN"}],"answer":"b","explanation":"Since \\[P = \\dfrac{\\pi^2EI}{L^2}\\] halving the length multiplies the load by 4, giving 4 kN.","marks":2,"source":{"kind":"past","set":4,"question":77,"marks":2,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q77 · 2 marks"},"topic":"ACiE0403"}]},{"name":"Design of Structures","questions":[{"id":"PAST-04-001","src":"PAST-04-001","text":"The shape factor of a rolled beam lies between","options":[{"key":"a","text":"1.10 to 1.20"},{"key":"b","text":"1.20 to 1.30"},{"key":"c","text":"1.30 to 1.40"},{"key":"d","text":"1.40 to 1.50"}],"answer":"a","explanation":"The shape factor Z<sub>p</sub>/Z<sub>e</sub> of standard rolled I-sections is about 1.10–1.20 (typically 1.12–1.14). It is 1.5 for a rectangle and 1.7 for a solid circle.","marks":1,"source":{"kind":"past","set":4,"question":1,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q1 · 1 mark"},"topic":"ACiE0505"},{"id":"PAST-04-024","src":"PAST-04-024","text":"Why is a circular column generally not used?","options":[{"key":"a","text":"It is uneconomical"},{"key":"b","text":"Difficult to connect to beam"},{"key":"c","text":"Low load carrying capacity"},{"key":"d","text":"All of the above"}],"answer":"b","explanation":"Rectangular beams frame awkwardly into a circular column, so formwork and detailing at the joints are difficult. Circular columns are used mainly where appearance or spiral confinement is needed.","marks":1,"source":{"kind":"past","set":4,"question":24,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q24 · 1 mark"},"topic":"ACiE0503"},{"id":"PAST-04-026","src":"PAST-04-026","text":"The slump test is used to measure","options":[{"key":"a","text":"Consistency"},{"key":"b","text":"Setting time"},{"key":"c","text":"Soundness"},{"key":"d","text":"Water content"}],"answer":"a","explanation":"The slump test measures the consistency (workability) of fresh concrete as the subsidence of a moulded cone.","marks":1,"source":{"kind":"past","set":4,"question":26,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q26 · 1 mark"},"topic":"ACiE0502"},{"id":"PAST-04-027","src":"PAST-04-027","text":"The moisture condition of aggregate used in concrete is","options":[{"key":"a","text":"Oven dry"},{"key":"b","text":"Air dry"},{"key":"c","text":"Saturated surface dry"},{"key":"d","text":"As available from surface"}],"answer":"c","explanation":"Mix design assumes saturated surface-dry (SSD) aggregate, which neither absorbs mixing water nor adds free water. Site aggregates are corrected to this state.","marks":1,"source":{"kind":"past","set":4,"question":27,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q27 · 1 mark"},"topic":"ACiE0502"},{"id":"PAST-04-030","src":"PAST-04-030","text":"In a slab, the minimum thickness is designed to resist","options":[{"key":"a","text":"Shear"},{"key":"b","text":"Tension"},{"key":"c","text":"Compression"},{"key":"d","text":"One-way shear"}],"answer":"c","explanation":"The slab depth is fixed so that the concrete can take the flexural compression, with limiting moment \\(M_{u,lim} \\propto f_{ck}bd^2\\), together with span-to-depth (deflection) limits. Tension is taken by the steel, and shear is rarely critical in slabs.","marks":1,"source":{"kind":"past","set":4,"question":30,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q30 · 1 mark"},"topic":"ACiE0503"},{"id":"PAST-04-038","src":"PAST-04-038","text":"In the case of cavity walls where both walls are load bearing, the effective thickness is","options":[{"key":"a","text":"Sum of both walls"},{"key":"b","text":"Thickness of stronger wall"},{"key":"c","text":"2/3 of sum of thickness of both walls"},{"key":"d","text":"Larger of b and c"}],"answer":"c","explanation":"IS 1905 takes the effective thickness of a cavity wall with both leaves load-bearing as two-thirds of the sum of the leaf thicknesses. (BS 5628 uses the greater of this and the thicker leaf.) The source key gives (b), which is not the code rule.","marks":1,"source":{"kind":"past","set":4,"question":38,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q38 · 1 mark"},"topic":"ACiE0506"},{"id":"PAST-04-055","src":"PAST-04-055","text":"What is the meaning of bulking of sand?","options":[{"key":"a","text":"Increase in volume of sand due to moisture absorption"},{"key":"b","text":"Increase in weight of sand due to moisture absorption"},{"key":"c","text":"Increase in mass of sand due to moisture absorption"},{"key":"d","text":"Increase in strength of sand due to moisture absorption"}],"answer":"a","explanation":"Thin water films around damp sand grains push them apart, so the loose volume increases (up to about 20–40% at 4–6% moisture). This is why sand is batched by weight or corrected for bulking.","marks":1,"source":{"kind":"past","set":4,"question":55,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q55 · 1 mark"},"topic":"ACiE0502"},{"id":"PAST-04-066","src":"PAST-04-066","text":"Strengths of a rivet in single shearing, in bearing and in tearing are 3425 kg, 4575 kg and 5025 kg respectively. If the load in the member is 35 tonnes, the number of rivets required is","options":[{"key":"a","text":"10"},{"key":"b","text":"11"},{"key":"c","text":"12"},{"key":"d","text":"13"}],"answer":"b","explanation":"The rivet value is the least strength, 3425 kg. The number of rivets is \\[n = \\dfrac{35{,}000}{3425} = 10.2\\] which rounds up to 11.","marks":2,"source":{"kind":"past","set":4,"question":66,"marks":2,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q66 · 2 marks"},"topic":"ACiE0505"}]},{"name":"Water Supply, Sanitation and Environment","questions":[{"id":"PAST-04-002","src":"PAST-04-002","text":"Water may not contain much impurities if its source is","options":[{"key":"a","text":"reservoirs"},{"key":"b","text":"stream flowing in plains"},{"key":"c","text":"lake in lower regions"},{"key":"d","text":"spring along hill slopes"}],"answer":"d","explanation":"Spring water on hill slopes has percolated through soil and rock, which filter it, and it has not collected surface runoff. It is therefore relatively free of suspended and organic impurities.","marks":1,"source":{"kind":"past","set":4,"question":2,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q2 · 1 mark"},"topic":"ACiE0601"},{"id":"PAST-04-008","src":"PAST-04-008","text":"Which of the following is the use of altitude valves?","options":[{"key":"a","text":"To allow water to flow in one direction only"},{"key":"b","text":"To blow off or remove the sand"},{"key":"c","text":"In the distribution system to shut off the supply whenever required"},{"key":"d","text":"Supplies water to elevated tanks or standpipes"}],"answer":"d","explanation":"An altitude valve on the inlet of an elevated tank or standpipe closes when the tank is full, preventing overflow, and reopens when the level falls.","marks":1,"source":{"kind":"past","set":4,"question":8,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q8 · 1 mark"},"topic":"ACiE0602"},{"id":"PAST-04-039","src":"PAST-04-039","text":"Harmful bacteria are called","options":[{"key":"a","text":"Parasites"},{"key":"b","text":"Aerobic"},{"key":"c","text":"Anaerobic"},{"key":"d","text":"Pathogen"}],"answer":"d","explanation":"Disease-causing bacteria (and other micro-organisms) are called pathogens. Aerobic and anaerobic describe oxygen needs, not harm.","marks":1,"source":{"kind":"past","set":4,"question":39,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q39 · 1 mark"},"topic":"ACiE0601"},{"id":"PAST-04-040","src":"PAST-04-040","text":"What is the opening spacing of bars in the case of a coarse screen?","options":[{"key":"a","text":"30 mm"},{"key":"b","text":"50 mm"},{"key":"c","text":"70 mm"},{"key":"d","text":"90 mm"}],"answer":"b","explanation":"Coarse screens (bar racks) have clear openings of about 50 mm or more. Medium screens are about 6–40 mm and fine screens are under 6 mm.","marks":1,"source":{"kind":"past","set":4,"question":40,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q40 · 1 mark"},"topic":"ACiE0605"},{"id":"PAST-04-041","src":"PAST-04-041","text":"An inverted siphon is provided when","options":[{"key":"a","text":"two sewers meet"},{"key":"b","text":"a sewer crosses a river"},{"key":"c","text":"two roads meet"},{"key":"d","text":"to empty out a sump"}],"answer":"b","explanation":"An inverted siphon (depressed sewer) carries a sewer under an obstruction such as a river, valley or railway cutting, running full under pressure.","marks":1,"source":{"kind":"past","set":4,"question":41,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q41 · 1 mark"},"topic":"ACiE0604"},{"id":"PAST-04-051","src":"PAST-04-051","text":"What is included in an impact assessment?","options":[{"key":"a","text":"A detailed assessment of the planned project and selected alternatives compared to the baseline conditions"},{"key":"b","text":"Qualitative descriptions measuring high, medium and low impacts"},{"key":"c","text":"Quantitative descriptions such as cubic metres of water withdrawn, sewage produced and pollutants released"},{"key":"d","text":"All the data collection, analysis and developed plans summarized in a well-structured and concise document"}],"answer":"d","explanation":"An impact assessment report brings together the baseline data, the analysis of alternatives, the predicted impacts (qualitative and quantitative) and the mitigation and monitoring plans in one structured document.","marks":1,"source":{"kind":"past","set":4,"question":51,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q51 · 1 mark"},"topic":"ACiE0606"},{"id":"PAST-04-058","src":"PAST-04-058","text":"Which method is used to measure the colour of water?","options":[{"key":"a","text":"Gravimetric analysis"},{"key":"b","text":"Spectrophotometric"},{"key":"c","text":"Tintometer method"},{"key":"d","text":"Hydrometer analysis"}],"answer":"c","explanation":"Colour is measured in platinum-cobalt (Hazen) units by comparing the sample with standard coloured glasses in a tintometer.","marks":1,"source":{"kind":"past","set":4,"question":58,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q58 · 1 mark"},"topic":"ACiE0601"},{"id":"PAST-04-059","src":"PAST-04-059","text":"Which of the following is a better test to identify coliforms?","options":[{"key":"a","text":"Coliform index"},{"key":"b","text":"Multiple tube fermentation"},{"key":"c","text":"MPN test"},{"key":"d","text":"Membrane filter technique"}],"answer":"d","explanation":"The membrane filter technique gives a direct colony count within about 24 hours and is more precise and reproducible than the statistical MPN (multiple-tube) method.","marks":1,"source":{"kind":"past","set":4,"question":59,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q59 · 1 mark"},"topic":"ACiE0601"},{"id":"PAST-04-070","src":"PAST-04-070","text":"Find the fire demand of 1 lakh population by Kuchling's formula.","options":[{"key":"a","text":"430 lit/sec"},{"key":"b","text":"530 lit/sec"},{"key":"c","text":"630 lit/sec"},{"key":"d","text":"730 lit/sec"}],"answer":"b","explanation":"Kuchling's formula, with \\(P\\) in thousands and \\(Q\\) in litres per minute, is \\[Q = 3182\\sqrt{P}\\] For \\(P = 100\\), \\(Q = 31{,}820\\) L per min, or about 530 L per s.","marks":2,"source":{"kind":"past","set":4,"question":70,"marks":2,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q70 · 2 marks"},"topic":"ACiE0601"}]},{"name":"Irrigation and Drainage","questions":[{"id":"PAST-04-004","src":"PAST-04-004","text":"For a saddle siphon, the maximum operative head is 4.53 m. The width and height of the throat of the siphon are 5 m and 2.25 m respectively. The coefficient of discharge is 0.90. How many units are required to pass a flood of 350 cumecs?","options":[{"key":"a","text":"One"},{"key":"b","text":"Two"},{"key":"c","text":"Three"},{"key":"d","text":"Four"}],"answer":"d","explanation":"The throat area is \\(A = 5 \\times 2.25 = 11.25\\) m<sup>2</sup>, and \\[\\begin{aligned} \\sqrt{2gH} &amp;= \\sqrt{2 \\times 9.81 \\times 4.53} \\\\ &amp;= 9.43 \\end{aligned}\\] so the discharge per unit is \\[\\begin{aligned} Q &amp;= C_dA\\sqrt{2gH} \\\\ &amp;= 0.9 \\times 11.25 \\times 9.43 \\\\ &amp;\\approx 95.4\\ \\text{m}^3\\text{/s} \\end{aligned}\\] so \\(\\dfrac{350}{95.4} = 3.7\\) and 4 units are needed.","marks":1,"source":{"kind":"past","set":4,"question":4,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q4 · 1 mark"},"topic":"ACiE0705"},{"id":"PAST-04-042","src":"PAST-04-042","text":"Water in a canal is based on","options":[{"key":"a","text":"Crop water requirement"},{"key":"b","text":"Net irrigation requirement"},{"key":"c","text":"Gross irrigation requirement"},{"key":"d","text":"Transpiration"}],"answer":"c","explanation":"The canal must carry the net requirement plus conveyance and application losses, i.e. the gross irrigation requirement (NIR ÷ efficiency).","marks":1,"source":{"kind":"past","set":4,"question":42,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q42 · 1 mark"},"topic":"ACiE0701"},{"id":"PAST-04-044","src":"PAST-04-044","text":"An energy dissipater is provided if the jump height is more than the tail water depth.","options":[{"key":"a","text":"Roller bucket"},{"key":"b","text":"Ski jump"},{"key":"c","text":"Sloping apron"},{"key":"d","text":"All of the above"}],"answer":"b","explanation":"When the tailwater is too low for a jump to form, a ski-jump (trajectory) bucket throws the jet clear so that it dissipates energy in the air and a downstream plunge pool. Roller buckets need high tailwater.","marks":1,"source":{"kind":"past","set":4,"question":44,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q44 · 1 mark"},"topic":"ACiE0703"},{"id":"PAST-04-053","src":"PAST-04-053","text":"The sensitivity of a rigid module is","options":[{"key":"a","text":"0"},{"key":"b","text":"1"},{"key":"c","text":"Between 0 and 1"},{"key":"d","text":"Infinity"}],"answer":"a","explanation":"A rigid module gives a fixed discharge regardless of changes in the distributary water level, so its sensitivity (ratio of the rate of change of outlet discharge to the rate of change of distributary level) is zero.","marks":1,"source":{"kind":"past","set":4,"question":53,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q53 · 1 mark"},"topic":"ACiE0705"},{"id":"PAST-04-062","src":"PAST-04-062","text":"In a syphon flume having length 100 m, width 10 m and depth 2 m, the velocity is reduced to 2.5 m/s. Calculate the head loss, given n = 0.015 for concrete lining.","options":[{"key":"a","text":"67 mm"},{"key":"b","text":"77 mm"},{"key":"c","text":"87 mm"},{"key":"d","text":"97 mm"}],"answer":"c","explanation":"The hydraulic radius is \\[R = \\dfrac{A}{P} = \\dfrac{10 \\times 2}{10 + 2 \\times 2} = 1.43\\] metres. Manning then gives \\[\\begin{aligned} h_f &amp;= \\dfrac{n^2V^2L}{R^{4{/}3}} \\\\ &amp;= \\dfrac{0.015^2 \\times 2.5^2 \\times 100}{1.43^{4{/}3}} \\\\ &amp;\\approx 0.087\\ \\text{m} = 87\\ \\text{mm} \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":4,"question":62,"marks":2,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q62 · 2 marks"},"topic":"ACiE0705"},{"id":"PAST-04-068","src":"PAST-04-068","text":"The cost of lining for 20 m perimeter is Rs 40/m<sup>2</sup>. The net area yields a saving of water of 3 cumecs per million m<sup>2</sup> of lining area, and each cumec of water yields crop production of Rs 3,00,000. If the life of the lining is 40 years, the maintenance cost is 12 paisa/m<sup>2</sup> and the annual interest rate is 6%, find the B/C ratio.","options":[{"key":"a","text":"1.2"},{"key":"b","text":"1.0"},{"key":"c","text":"0.85"},{"key":"d","text":"0.8"}],"answer":"d","explanation":"Take 1 km of canal, so the lining area is 20,000 m<sup>2</sup> and the cost is Rs 8,00,000. The water saving is 3 cumecs per million m<sup>2</sup>, or 0.06 cumec here, so the annual benefit is \\[0.06 \\times 3{,}00{,}000 = \\text{Rs } 18{,}000\\] With straight-line depreciation, the annual cost is \\[\\begin{aligned} &amp;\\dfrac{8{,}00{,}000}{40} + 0.12 \\times 20{,}000 \\\\ &amp;= \\text{Rs } 22{,}400 \\end{aligned}\\] so \\[\\dfrac{B}{C} = \\dfrac{18{,}000}{22{,}400} \\approx 0.80\\] The source key gives (b), which the data do not support. Discounting the capital at 6% (capital recovery) would lower the ratio further, to about 0.32.","marks":2,"source":{"kind":"past","set":4,"question":68,"marks":2,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q68 · 2 marks"},"topic":"ACiE0702"},{"id":"PAST-04-079","src":"PAST-04-079","text":"The length of the upstream guide bank is …… than the downstream guide bank length.","options":[{"key":"a","text":"Greater"},{"key":"b","text":"Lesser"},{"key":"c","text":"Same"},{"key":"d","text":"Depends on site conditions"}],"answer":"a","explanation":"Guide banks usually extend about 1.0-1.5 L upstream and only 0.2-0.4 L downstream (L being the bridge length), so the upstream bank is longer.","marks":2,"source":{"kind":"past","set":4,"question":79,"marks":2,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q79 · 2 marks"},"topic":"ACiE0704"},{"id":"PAST-04-080","src":"PAST-04-080","text":"The mean depth of water is 1.5 cm and the mean deviation from the mean is 0.1 cm. Determine its distribution efficiency.","options":[{"key":"a","text":"87%"},{"key":"b","text":"83%"},{"key":"c","text":"90%"},{"key":"d","text":"93%"}],"answer":"d","explanation":"With mean depth \\(d\\) and mean deviation \\(y\\), \\[\\eta_d = \\left(1 - \\dfrac{y}{d}\\right) \\times 100\\] \\[= \\left(1 - \\dfrac{0.1}{1.5}\\right) \\times 100 \\approx 93\\%\\]","marks":2,"source":{"kind":"past","set":4,"question":80,"marks":2,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q80 · 2 marks"},"topic":"ACiE0701"}]},{"name":"Hydropower","questions":[{"id":"PAST-04-010","src":"PAST-04-010","text":"For the same power output, which power plant has the minimum operating charges?","options":[{"key":"a","text":"Hydropower plant"},{"key":"b","text":"Nuclear plant"},{"key":"c","text":"Thermal plant"},{"key":"d","text":"Gas turbine plant"}],"answer":"a","explanation":"A hydropower plant uses no fuel and needs few operators, so its running cost is the lowest, even though its capital cost is high.","marks":1,"source":{"kind":"past","set":4,"question":10,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q10 · 1 mark"},"topic":"ACiE0802"},{"id":"PAST-04-011","src":"PAST-04-011","text":"The power needed to lift water can be calculated as","options":[{"key":"a","text":"P = γAH"},{"key":"b","text":"P = γQH"},{"key":"c","text":"P = γA/H"},{"key":"d","text":"P = γQ/H"}],"answer":"b","explanation":"Hydraulic power is \\[P = \\gamma QH\\] in watts, with \\(\\gamma\\) in N per m<sup>3</sup>, \\(Q\\) in m<sup>3</sup> per s and \\(H\\) in m. The shaft power is this value divided by the pump efficiency.","marks":1,"source":{"kind":"past","set":4,"question":11,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q11 · 1 mark"},"topic":"ACiE0802"},{"id":"PAST-04-028","src":"PAST-04-028","text":"Which of the following is an impulse turbine?","options":[{"key":"a","text":"Francis"},{"key":"b","text":"Kaplan"},{"key":"c","text":"Pelton"},{"key":"d","text":"Propeller"}],"answer":"c","explanation":"In a Pelton wheel the whole head is converted into jet velocity before it strikes the buckets at atmospheric pressure, which makes it an impulse turbine. Francis, Kaplan and propeller turbines are reaction turbines.","marks":1,"source":{"kind":"past","set":4,"question":28,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q28 · 1 mark"},"topic":"ACiE0806"},{"id":"PAST-04-043","src":"PAST-04-043","text":"What is a load factor?","options":[{"key":"a","text":"The ratio of average to maximum demand"},{"key":"b","text":"The ratio of maximum demand to average load"},{"key":"c","text":"The product of max demand and average load"},{"key":"d","text":"The product of max. demand and average load"}],"answer":"a","explanation":"Over a period, \\[\\text{LF} = \\dfrac{\\text{average load}}{\\text{maximum demand}}\\] It is always less than 1.","marks":1,"source":{"kind":"past","set":4,"question":43,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q43 · 1 mark"},"topic":"ACiE0802"},{"id":"PAST-04-045","src":"PAST-04-045","text":"Which is used to protect turbine and runner from damage?","options":[{"key":"a","text":"Surge tank"},{"key":"b","text":"Fuel tank"},{"key":"c","text":"Power house"},{"key":"d","text":"Penstock"}],"answer":"a","explanation":"A surge tank absorbs the pressure rise (water hammer) when the turbine gates close suddenly and supplies water when they open, protecting the penstock, turbine and runner.","marks":1,"source":{"kind":"past","set":4,"question":45,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q45 · 1 mark"},"topic":"ACiE0805"},{"id":"PAST-04-049","src":"PAST-04-049","text":"Which one of the following statements is not correct for the heading and benching method of tunnelling?","options":[{"key":"a","text":"Drilling and mucking can be done simultaneously"},{"key":"b","text":"Benching provides a platform for working on the heading"},{"key":"c","text":"Removal of muck from the heading is very easy"},{"key":"d","text":"None of these"}],"answer":"c","explanation":"The heading is driven ahead of the bench, so its muck must be dropped or carried over the bench. Mucking from the heading is therefore not easy; the other two statements are true.","marks":1,"source":{"kind":"past","set":4,"question":49,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q49 · 1 mark"},"topic":"ACiE0805"},{"id":"PAST-04-057","src":"PAST-04-057","text":"Draft tubes are not used in which of the following turbines?","options":[{"key":"a","text":"Francis"},{"key":"b","text":"Reaction"},{"key":"c","text":"Kaplan"},{"key":"d","text":"Pelton"}],"answer":"d","explanation":"A Pelton wheel is an impulse turbine that discharges at atmospheric pressure, so a draft tube cannot recover any head. Reaction turbines (Francis, Kaplan) need one.","marks":1,"source":{"kind":"past","set":4,"question":57,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q57 · 1 mark"},"topic":"ACiE0806"},{"id":"PAST-04-064","src":"PAST-04-064","text":"Pick up the correct statement from the following during tunnel excavation.","options":[{"key":"a","text":"Oxygen should not be less than 19.5%"},{"key":"b","text":"Hydrogen sulphide should not be more than 0.001%"},{"key":"c","text":"Carbon dioxide should not be more than 0.5%"},{"key":"d","text":"All of these"}],"answer":"d","explanation":"Tunnel ventilation must keep oxygen at 19.5% or more and toxic gases below their limits (for example H<sub>2</sub>S about 10 ppm, or 0.001%, and CO<sub>2</sub> 0.5%). All three statements hold.","marks":2,"source":{"kind":"past","set":4,"question":64,"marks":2,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q64 · 2 marks"},"topic":"ACiE0805"},{"id":"PAST-04-065","src":"PAST-04-065","text":"A turbine develops 2000 hp under a head of 150 m while running at 300 rpm. What is the specific speed?","options":[{"key":"a","text":"10-35"},{"key":"b","text":"35-60"},{"key":"c","text":"60-300"},{"key":"d","text":"300-1000"}],"answer":"a","explanation":"The specific speed is \\[\\begin{aligned} N_s &amp;= \\dfrac{N\\sqrt{P}}{H^{5{/}4}} \\\\ &amp;= \\dfrac{300 \\times \\sqrt{2000}}{150^{1.25}} \\\\ &amp;\\approx \\dfrac{13{,}416}{525} \\approx 25.6 \\end{aligned}\\] This lies in the 10-35 range, which is typical of a Pelton wheel.","marks":2,"source":{"kind":"past","set":4,"question":65,"marks":2,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q65 · 2 marks"},"topic":"ACiE0806"},{"id":"PAST-04-074","src":"PAST-04-074","text":"If the operating cost is high but the plant offers great flexibility, the plant is used for","options":[{"key":"a","text":"Base load only"},{"key":"b","text":"Peak load only"},{"key":"c","text":"Base load and peak load"},{"key":"d","text":"We don't use such plant"}],"answer":"b","explanation":"Plants that start and follow load quickly but are costly to run (for example diesel or gas turbines) are run only for short peak periods.","marks":2,"source":{"kind":"past","set":4,"question":74,"marks":2,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q74 · 2 marks"},"topic":"ACiE0802"}]},{"name":"Transportation","questions":[{"id":"PAST-04-012","src":"PAST-04-012","text":"Which is the binding material used in road pavement?","options":[{"key":"a","text":"Stone dust"},{"key":"b","text":"Bitumen"},{"key":"c","text":"Cement"},{"key":"d","text":"Lime"}],"answer":"b","explanation":"In flexible (bituminous) pavements, bitumen is the binder that coats and holds the aggregates together.","marks":1,"source":{"kind":"past","set":4,"question":12,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q12 · 1 mark"},"topic":"ACiE0903"},{"id":"PAST-04-017","src":"PAST-04-017","text":"The minimum value of the 15-minute peak hour factor on a section of a road is","options":[{"key":"a","text":"0.15"},{"key":"b","text":"0.20"},{"key":"c","text":"0.25"},{"key":"d","text":"0.30"}],"answer":"c","explanation":"The peak-hour factor is \\[\\text{PHF} = \\dfrac{V}{4V_{15}}\\] If the entire hour's traffic arrived in one 15-min interval, \\(V_{15} = V\\) and \\[\\text{PHF} = \\dfrac{V}{4V} = 0.25\\] its theoretical minimum. Its maximum is 1.0.","marks":1,"source":{"kind":"past","set":4,"question":17,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q17 · 1 mark"},"topic":"ACiE0904"},{"id":"PAST-04-046","src":"PAST-04-046","text":"Which of the following is not related to the cross section of a road?","options":[{"key":"a","text":"Camber"},{"key":"b","text":"Super elevation"},{"key":"c","text":"Lanes"},{"key":"d","text":"Gradient"}],"answer":"d","explanation":"Camber, superelevation and the number/width of lanes are all cross-section elements. Gradient is the longitudinal slope, an element of the vertical profile. The source key gives (c), but lanes are part of the cross section.","marks":1,"source":{"kind":"past","set":4,"question":46,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q46 · 1 mark"},"topic":"ACiE0902"},{"id":"PAST-04-047","src":"PAST-04-047","text":"In which stage of survey is the soil survey done?","options":[{"key":"a","text":"Preliminary survey"},{"key":"b","text":"Reconnaissance"},{"key":"c","text":"Map study"},{"key":"d","text":"Topography study"}],"answer":"a","explanation":"Soil samples along the alternative alignments are collected and tested during the preliminary survey, after map study and reconnaissance.","marks":1,"source":{"kind":"past","set":4,"question":47,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q47 · 1 mark"},"topic":"ACiE0901"},{"id":"PAST-04-050","src":"PAST-04-050","text":"Which of the following rollers is used to compact coarse-grained soil?","options":[{"key":"a","text":"Drum roller"},{"key":"b","text":"Pneumatic roller"},{"key":"c","text":"Vibratory roller"},{"key":"d","text":"Tamping roller"}],"answer":"c","explanation":"Vibration rearranges cohesionless grains into a dense packing, so vibratory rollers suit sands and gravels. Tamping (sheepsfoot) rollers suit cohesive soils.","marks":1,"source":{"kind":"past","set":4,"question":50,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q50 · 1 mark"},"topic":"ACiE0906"},{"id":"PAST-04-072","src":"PAST-04-072","text":"Calculate the ruling minimum radius for f = 0.36, e = 0 and v = 35 kmph.","options":[{"key":"a","text":"16 m"},{"key":"b","text":"27 m"},{"key":"c","text":"36 m"},{"key":"d","text":"49 m"}],"answer":"b","explanation":"The ruling minimum radius is \\[\\begin{aligned} R &amp;= \\dfrac{v^2}{127(e + f)} \\\\ &amp;= \\dfrac{35^2}{127 \\times 0.36} \\\\ &amp;= \\dfrac{1225}{45.7} \\approx 27\\ \\text{m} \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":4,"question":72,"marks":2,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q72 · 2 marks"},"topic":"ACiE0902"}]},{"name":"Project Planning, Design and Implementation","questions":[{"id":"PAST-04-009","src":"PAST-04-009","text":"When did the Government of Nepal form the Nepal Engineering Council?","options":[{"key":"a","text":"2055"},{"key":"b","text":"2056"},{"key":"c","text":"2057"},{"key":"d","text":"2058"}],"answer":"a","explanation":"The Nepal Engineering Council was constituted under the Nepal Engineering Council Act, 2055 B.S. (1998 AD).","marks":1,"source":{"kind":"past","set":4,"question":9,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q9 · 1 mark"},"topic":"AALL1006"},{"id":"PAST-04-014","src":"PAST-04-014","text":"In resource levelling, which of the following is the constraint?","options":[{"key":"a","text":"Time"},{"key":"b","text":"Money"},{"key":"c","text":"Resources"},{"key":"d","text":"Both time and resources"}],"answer":"c","explanation":"In resource levelling, the limited resource availability is the constraint and the project duration may extend. In resource smoothing, time is the constraint.","marks":1,"source":{"kind":"past","set":4,"question":14,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q14 · 1 mark"},"topic":"AALL1003"},{"id":"PAST-04-015","src":"PAST-04-015","text":"For incremental analysis, the initial investment must be","options":[{"key":"a","text":"Maximum"},{"key":"b","text":"Average"},{"key":"c","text":"Minimum"},{"key":"d","text":"Zero"}],"answer":"c","explanation":"Incremental analysis starts with the alternative of lowest initial investment as the defender. Each costlier alternative is then compared on its increment.","marks":1,"source":{"kind":"past","set":4,"question":15,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q15 · 1 mark"},"topic":"AALL1002"},{"id":"PAST-04-016","src":"PAST-04-016","text":"Which of the following is an unsafe share?","options":[{"key":"a","text":"Preference shares"},{"key":"b","text":"Primary shares"},{"key":"c","text":"Debentures"},{"key":"d","text":"All"}],"answer":"b","explanation":"In liquidation, debenture holders (creditors) are paid first, then preference shareholders. Ordinary (primary/equity) shareholders are paid last, so their investment is the riskiest.","marks":1,"source":{"kind":"past","set":4,"question":16,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q16 · 1 mark"},"topic":"AALL1002"},{"id":"PAST-04-022","src":"PAST-04-022","text":"Which of the following is a characteristic of a profession?","options":[{"key":"a","text":"It enjoys a high level of public trust and confidence"},{"key":"b","text":"It is organized into associations"},{"key":"c","text":"There are published authoritative performance and ethical standards"},{"key":"d","text":"All of the above are characteristics of a profession"}],"answer":"d","explanation":"A profession rests on specialised knowledge. Its members are organised in professional bodies, follow published codes of ethics and standards, and hold public trust.","marks":1,"source":{"kind":"past","set":4,"question":22,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q22 · 1 mark"},"topic":"AALL1005"},{"id":"PAST-04-054","src":"PAST-04-054","text":"If 'a' is the base amount of expenditure and 'b' is the increase in the operation cost each year over a period of 'n' years, the total cost of maintenance is","options":[{"key":"a","text":"a+(n+1)b"},{"key":"b","text":"a(n-1)b"},{"key":"c","text":"a+(n-1)b"},{"key":"d","text":"a-(n-1)b"}],"answer":"c","explanation":"With a uniform gradient the cost is a in year 1, a+b in year 2 and so on, so the cost in year n is a+(n-1)b.","marks":1,"source":{"kind":"past","set":4,"question":54,"marks":1,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q54 · 1 mark"},"topic":"AALL1002"},{"id":"PAST-04-067","src":"PAST-04-067","text":"The difference between the maximum time available and the actual time needed to perform an activity is known as","options":[{"key":"a","text":"Free float"},{"key":"b","text":"Independent float"},{"key":"c","text":"Total float"},{"key":"d","text":"Half float"}],"answer":"c","explanation":"Total float is the maximum time available minus the activity duration: \\[\\text{TF} = (\\text{LF} - \\text{ES}) - D\\]","marks":2,"source":{"kind":"past","set":4,"question":67,"marks":2,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q67 · 2 marks"},"topic":"AALL1003"},{"id":"PAST-04-075","src":"PAST-04-075","text":"IRR is calculated","options":[{"key":"a","text":"When NPV is less than zero"},{"key":"b","text":"When NPV is more than zero"},{"key":"c","text":"When NPV is equal to zero"},{"key":"d","text":"When NPV is equal to MARR"}],"answer":"c","explanation":"The internal rate of return is the discount rate at which the net present value of the cash flows becomes zero.","marks":2,"source":{"kind":"past","set":4,"question":75,"marks":2,"date":"2080 Mangsir 23","shift":"3rd shift","reference":"Past Paper Set 4, Q75 · 2 marks"},"topic":"AALL1002"}]}]};
